const S=window.__forja,C=window.__classes,AB=window.__abilities,SK=window.__skills;
document.head.insertAdjacentHTML('beforeend','<style>.campaign-open{margin-top:18px}.entry{display:flex;justify-content:space-between;gap:10px;align-items:center;border-top:1px solid #e5e1d8;padding:9px 0;font-size:12px}.entry button{border:0;background:none;color:#a33b2f;font-weight:700;cursor:pointer}.campaign-note{font-size:11px;color:#77766f;line-height:1.5}.axis{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:8px}.origin-bonuses{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-top:12px}@media(max-width:560px){.origin-bonuses{grid-template-columns:1fr}}</style>');
const XP_LEVELS=[0,300,900,2700,6500,14000,23000,34000,48000,64000,85000,100000,120000,140000,165000,195000,225000,265000,305000,355000];
const SPECIES24=['Draconato','Anão','Elfo','Gnomo','Golias','Halfling','Humano','Orc','Tiefling'];
const BG24={
 'Acólito':{skills:['Intuição','Religião'],stats:['INT','WIS','CHA'],feat:'Iniciado em Magia (Clérigo)',tool:'Suprimentos de calígrafo'},
 'Criminoso':{skills:['Prestidigitação','Furtividade'],stats:['DEX','CON','INT'],feat:'Alerta',tool:'Ferramentas de ladrão'},
 'Sábio':{skills:['Arcanismo','História'],stats:['CON','INT','WIS'],feat:'Iniciado em Magia (Mago)',tool:'Suprimentos de calígrafo'},
 'Soldado':{skills:['Atletismo','Intimidação'],stats:['STR','DEX','CON'],feat:'Atacante Selvagem',tool:'Um conjunto de jogo'}
};
const SK24={Bar:['Adestrar Animais','Atletismo','Intimidação','Natureza','Percepção','Sobrevivência'],Bard:Object.keys(SK),Cleric:['História','Intuição','Medicina','Persuasão','Religião'],Druid:['Arcanismo','Adestrar Animais','Intuição','Medicina','Natureza','Percepção','Religião','Sobrevivência'],Fighter:['Acrobacia','Adestrar Animais','Atletismo','História','Intuição','Intimidação','Persuasão','Percepção','Sobrevivência'],Monk:['Acrobacia','Atletismo','História','Intuição','Religião','Furtividade'],Paladin:['Atletismo','Intuição','Intimidação','Medicina','Persuasão','Religião'],Ranger:['Adestrar Animais','Atletismo','Intuição','Investigação','Natureza','Percepção','Furtividade','Sobrevivência'],Rogue:['Acrobacia','Atletismo','Enganação','Intuição','Intimidação','Investigação','Percepção','Persuasão','Prestidigitação','Furtividade'],Sorcerer:['Arcanismo','Enganação','Intuição','Intimidação','Persuasão','Religião'],Warlock:['Arcanismo','Enganação','História','Intimidação','Investigação','Natureza','Religião'],Wizard:['Arcanismo','História','Intuição','Investigação','Medicina','Natureza','Religião']};
Object.keys(SK24).forEach(k=>C[k].opts=SK24[k]);
S.backgroundSkill='';S.moralAxis=S.moralAxis||'Neutro';S.orderAxis=S.orderAxis||'Neutro';S.baseScores=S.baseScores||{...S.scores};window.__selected={...S.baseScores};S.originBoosts=S.originBoosts||{a:'INT',b:'WIS',mode:'2+1'};S.currentHP=S.currentHP==null?0:S.currentHP;S.tempHP=S.tempHP||0;S.gold=S.gold||0;S.inventory=S.inventory||[];S.featuresLog=S.featuresLog||[];S.journal=S.journal||[];S.level=Math.max(1,Math.min(20,Number(S.level)||1));

document.querySelector('.edition').textContent='D&D 2024 · nível 1 para começar';
document.querySelector('.hero p').textContent='Monte sua ficha e continue usando durante a campanha: registre nível, itens, habilidades, PV, XP e anotações.';
document.querySelector('.footer').textContent='FORJA · ficha digital baseada no SRD 5.2.1 · D&D 2024';
