const ARMOR24={'Sem armadura':{base:10,dex:99},'Couro':{base:11,dex:99},'Couro batido':{base:12,dex:99},'Gibão de peles':{base:12,dex:2},'Camisa de cota de malha':{base:13,dex:2},'Brunea':{base:14,dex:2},'Peitoral':{base:14,dex:2},'Meia armadura':{base:15,dex:2},'Cota de anéis':{base:14,dex:0},'Cota de malha':{base:16,dex:0},'Cota de talas':{base:17,dex:0},'Armadura de placas':{base:18,dex:0}};
function automaticSpeed(){let base=speciesSpeed(S.race),armor=S.wornArmor||'Sem armadura',heavy=['Cota de malha','Cota de talas','Armadura de placas'].includes(armor),strengthNeed={'Cota de malha':13,'Cota de talas':15,'Armadura de placas':15}[armor]||0;if(strengthNeed&&Number(S.scores.STR)<strengthNeed)base-=10;if(S.cls==='Monk'&&armor==='Sem armadura'&&!S.shieldEquipped)base+=S.level>=18?30:S.level>=14?25:S.level>=10?20:S.level>=6?15:S.level>=2?10:0;else if(S.cls==='Bar'&&S.level>=5&&!heavy)base+=10;else if(S.cls==='Ranger'&&S.level>=6&&!heavy)base+=10;return base}
automaticAC=function(){let dex=mod(S.scores.DEX),name=S.wornArmor||'Sem armadura',armor=ARMOR24[name]||ARMOR24['Sem armadura'],base;if(name==='Sem armadura')base=10+dex+(S.cls==='Monk'&&!S.shieldEquipped?mod(S.scores.WIS):S.cls==='Bar'?mod(S.scores.CON):0);else base=armor.base+(armor.dex===0?0:Math.min(armor.dex,dex));return base+(S.shieldEquipped?2:0)};
