const syncResourceBase=syncResources;
syncResources=function(){let before=Object.fromEntries(S.resources.filter(r=>r.builtin).map(r=>[r.name,Number(r.max)||0]));syncResourceBase();S.resources.forEach(r=>{if(!r.builtin)return;let gained=Math.max(0,(Number(r.max)||0)-(before[r.name]||0));if(gained)r.current=Math.min(r.max,(Number(r.current)||0)+gained);if(r.name==='Inspiração de Bardo'){r.rest=S.level>=5?'Descanso curto':'Descanso longo';r.shortAmount=S.level>=5?'all':0}if(r.name==='Canalizar Divindade'){r.max=(S.cls==='Cleric'?S.level>=2?2:0:S.level>=3?2:0);r.current=Math.min(r.current,r.max);r.rest='Descanso curto ou longo';r.shortAmount=1}if(r.name==='Usos de Fúria'){r.rest='Descanso curto ou longo';r.shortAmount=1}if(r.name==='Segundo Fôlego'){r.rest='Descanso curto ou longo';r.shortAmount=1}if(r.name==='Surto de Ação'){r.rest='Descanso curto ou longo';r.shortAmount='all'}if(r.name==='Forma Selvagem'||r.name==='Pontos de Foco'||r.name==='Espaços de Pacto'){r.rest='Descanso curto ou longo';r.shortAmount='all'}if(r.name==='Marca do Caçador sem espaço'||r.name==='Pontos de Feitiçaria'||r.name==='Recuperação Arcana'){r.rest='Descanso longo';r.shortAmount=0}})};
renderResources=function(){syncResources();let root=document.getElementById('resourcesList');if(!root)return;root.innerHTML=S.resources.filter(r=>r.max>0).map(r=>{let i=S.resources.indexOf(r);return '<div class="resource-row"><div><b>'+escapeCampaign(r.name)+'</b><small>'+escapeCampaign(r.rest||'Uso rastreável')+'</small></div><button class="btn" onclick="changeResource('+i+',-1)">−</button><strong>'+r.current+' / '+r.max+'</strong><button class="btn" onclick="changeResource('+i+',1)">+</button>'+(r.builtin?'':'<button class="entry-remove" onclick="removeResource('+i+')">×</button>')+'</div>'}).join('')+'<div class="grid" style="margin-top:10px"><div class="field"><label for="resourceName">Novo recurso</label><input id="resourceName" placeholder="Ex.: carga de item mágico"></div><div class="field"><label for="resourceMax">Usos máximos</label><input id="resourceMax" type="number" min="1" value="1"></div></div><button class="btn" style="margin-top:8px" onclick="addResource()">Adicionar recurso</button>'};
recoverResources=function(type){S.resources.forEach(r=>{if(type==='long')r.current=r.max;else if(r.shortAmount==='all')r.current=r.max;else if(Number(r.shortAmount)>0)r.current=Math.min(r.max,r.current+Number(r.shortAmount))});save();renderCampaign()};
longRest=function(){if(!confirm('Descanso longo: recuperar PV e recursos?'))return;S.currentHP=derived().hp;S.tempHP=0;S.resources.forEach(r=>r.current=r.max);save();renderCampaign();toast('PV e recursos recuperados.')};
