// Campo de magias com espaços calculados pela classe e lista de magias do jogador.
S.spells=S.spells||[];S.spellSlots=S.spellSlots||{};
const FULL_SLOTS=[[2],[3],[4,2],[4,3],[4,3,2],[4,3,3],[4,3,3,1],[4,3,3,2],[4,3,3,3,1],[4,3,3,3,2],[4,3,3,3,2,1],[4,3,3,3,2,1],[4,3,3,3,2,1,1],[4,3,3,3,2,1,1],[4,3,3,3,2,1,1,1],[4,3,3,3,2,1,1,1],[4,3,3,3,2,1,1,1,1]];
function slotsForCharacter(){if(['Bar','Fighter','Monk','Rogue'].includes(S.cls))return[];if(S.cls==='Warlock'){let n=S.level>=17?4:S.level>=11?3:S.level>=2?2:1,spellLevel=S.level>=9?5:S.level>=7?4:S.level>=5?3:S.level>=3?2:1;return Array.from({length:spellLevel},(_,i)=>i===spellLevel-1?n:0)}let casterLevel=['Paladin','Ranger'].includes(S.cls)?Math.ceil(S.level/2):S.level;return FULL_SLOTS[Math.max(0,Math.min(16,casterLevel-1))]||[]}
function syncSpellSlots(){let totals=slotsForCharacter();for(let i=0;i<9;i++){let name=String(i+1),max=Number(totals[i]||0),entry=S.spellSlots[name];if(!entry)S.spellSlots[name]={max,current:max};else{let increase=Math.max(0,max-entry.max);entry.max=max;entry.current=Math.min(max,entry.current+increase)}}}
function renderSpells(){syncSpellSlots();let root=document.getElementById('spellListArea');if(!root)return;let slots=Object.entries(S.spellSlots).filter(([,v])=>v.max>0);root.innerHTML='<h4>Espaços de magia</h4><p class="campaign-note">Você gasta um espaço ao conjurar uma magia de nível 1 ou maior. Truques não gastam espaços. Bruxos recuperam os espaços de pacto no descanso curto; outras classes recuperam no longo.</p><div class="slot-grid">'+slots.map(([level,v])=>'<div class="slot"><span>Nível '+level+'</span><button class="btn" onclick="spendSlot(\''+level+'\',-1)">−</button><b>'+v.current+' / '+v.max+'</b><button class="btn" onclick="spendSlot(\''+level+'\',1)">+</button></div>').join('')+'</div><h4>Magias conhecidas ou preparadas</h4><div class="grid"><div class="field"><label for="spellNameInput">Nome da magia</label><input id="spellNameInput" placeholder="Ex.: Curar Ferimentos"></div><div class="field"><label for="spellLevelInput">Nível</label><select id="spellLevelInput"><option value="0">Truque</option>'+Array.from({length:9},(_,i)=>'<option value="'+(i+1)+'">'+(i+1)+'º círculo</option>').join('')+'</select></div></div><button class="btn" style="margin:8px 0" onclick="addSpell()">Adicionar magia</button><div>'+ (S.spells.length?S.spells.map((sp,i)=>'<div class="entry"><span><b>'+escapeCampaign(sp.name)+'</b> · '+(sp.level===0?'Truque':sp.level+'º círculo')+' · <label><input type="checkbox" '+(sp.prepared?'checked':'')+' onchange="togglePrepared('+i+',this.checked)"> preparada</label></span><button onclick="removeSpell('+i+')">Remover</button></div>').join(''):'<p class="campaign-note">Ainda não há magias anotadas.</p>')+'</div>'}
function spendSlot(level,amount){let s=S.spellSlots[level];s.current=Math.max(0,Math.min(s.max,s.current+amount));save();renderSpells()}
function addSpell(){let name=document.getElementById('spellNameInput').value.trim(),level=Number(document.getElementById('spellLevelInput').value);if(!name)return toast('Digite o nome da magia.');S.spells.push({name,level,prepared:true});save();renderCampaign()}
function togglePrepared(i,v){S.spells[i].prepared=v;save()}
