recoverResources=function(type){shortRestWithSpells(type);if(type==='long'&&S.cls!=='Warlock'){Object.values(S.spellSlots).forEach(x=>x.current=x.max);save();renderSpells()}if(type==='short'&&S.cls==='Warlock'){Object.values(S.spellSlots).forEach(x=>x.current=x.max);save();renderSpells()}};
